import { Container, Sprite, Texture } from 'pixi.js';

import { IPointerEvent } from '../../types/cabinet';

export class CabinetButtonView extends Container {
    public touchStartTime: number = 0;

    private pointerEvents?: Array<IPointerEvent>;
    private defaultButtonTexture: Texture;

    protected buttonSprite: Sprite;

    public get dimensions(): { width: number; height: number } { return { width: this.buttonSprite.texture.width, height: this.buttonSprite.texture.height }; }

    constructor(buttonTexture: Texture, pointerEvents?: IPointerEvent[]) {
        super();

        this.defaultButtonTexture = buttonTexture;
        this.pointerEvents = pointerEvents;

        this.setButtonTexture(buttonTexture);
        this.setButtonListeners();

        this.buttonSprite.on('pointerdown', () => { this.touchStartTime = Date.now(); });
        this.buttonSprite.interactive = true;
        this.buttonSprite.cursor = 'pointer';
        this.buttonSprite.name = 'button-sprite';
    }

    public get defaultTexture(): Texture { return this.defaultButtonTexture; }

    public set interactionEnabled(value: boolean) {
        this.buttonSprite.interactive = value;
        this.buttonSprite.cursor = value ? 'pointer' : undefined;
    }

    /** @deprecated We no longer support the tinting of the cabinet buttons, so this function has no implementation. */
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    public updateColour(colour: number): void {
        // No Implementation
    }

    /** @deprecated `setIconTexture` is no longer used. Please use `changeButtonTexture` instead. */
    public setIconTexture(texture: Texture): void {
        this.setButtonTexture(texture);
    }

    public enable(value: boolean) {
        this.interactionEnabled = value;
        this.alpha = value ? 1 : 0.5;
    }

    public changeButtonTexture(texture: Texture): void {
        this.buttonSprite.texture = texture;
    }

    public resetButtonTexture(): void {
        if (this.defaultButtonTexture) { this.changeButtonTexture(this.defaultButtonTexture); }
    }

    protected setButtonListeners(): void {
        if (this.pointerEvents) { this.pointerEvents.forEach((event) => { this.buttonSprite.on(event.pointerEvent, event.callback, this); }); }
    }

    private setButtonTexture(buttonTexture: Texture) {
        this.buttonSprite = new Sprite(buttonTexture);
        this.buttonSprite.anchor.set(0.5);

        this.addChild(this.buttonSprite);
    }
}